CREATE TABLE IF NOT EXISTS "Departments" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Name" text NOT NULL);
CREATE TABLE IF NOT EXISTS "Employees" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Name" text NOT NULL,"Department" text NOT NULL,"Salary" numeric NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "Tickets" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Title" text NOT NULL,"Department" text NOT NULL,"CreatedBy" text NOT NULL,"Status" text NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS "Products" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Name" text NOT NULL,"Price" numeric NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "Advertisements" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Title" text NOT NULL,"Content" text NOT NULL,"Published" boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS "Audits" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Actor" text NOT NULL,"Action" text NOT NULL,"Target" text NOT NULL,"Details" text NOT NULL,"CreatedAt" timestamp with time zone NOT NULL DEFAULT now());
INSERT INTO "Departments"("Name") SELECT 'Network' WHERE NOT EXISTS (SELECT 1 FROM "Departments" WHERE "Name"='Network');
INSERT INTO "Departments"("Name") SELECT 'Human Resources' WHERE NOT EXISTS (SELECT 1 FROM "Departments" WHERE "Name"='Human Resources');
